describe('Focus Indicators Visibility on Interactive Elements', () => {
  beforeEach(() => {
    cy.visit('/interactive-elements');
  });

  it('should display focus indicators on all interactive elements when tabbing through', () => {
    // Verify initial state with no focus
    cy.get('[data-testid="button-1"]').should('not.have.class', 'focus-indicator');
    cy.get('[data-testid="input-field"]').should('not.have.class', 'focus-indicator');
    cy.get('[data-testid="dropdown-menu"]').should('not.have.class', 'focus-indicator');

    // Tab through elements
    cy.get('[data-testid="button-1"]').click();
    cy.get('[data-testid="button-1"]').should('have.class', 'focus-indicator');

    cy.get('[data-testid="input-field"]').click();
    cy.get('[data-testid="input-field"]').should('have.class', 'focus-indicator');

    cy.get('[data-testid="dropdown-menu"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('have.class', 'focus-indicator');

    // Verify focus indicators are visible on all elements
    cy.get('[data-testid="button-1"]').should('have.class', 'focus-indicator');
    cy.get('[data-testid="input-field"]').should('have.class', 'focus-indicator');
    cy.get('[data-testid="dropdown-menu"]').should('have.class', 'focus-indicator');
  });

  it('should remove focus indicators when element loses focus', () => {
    // Tab to first interactive element
    cy.get('[data-testid="button-1"]').click();
    cy.get('[data-testid="button-1"]').should('have.class', 'focus-indicator');

    // Tab to second interactive element
    cy.get('[data-testid="input-field"]').click();
    cy.get('[data-testid="input-field"]').should('have.class', 'focus-indicator');

    // Tab to third interactive element
    cy.get('[data-testid="dropdown-menu"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('have.class', 'focus-indicator');

    // Tab back to first element
    cy.get('[data-testid="button-1"]').click();
    cy.get('[data-testid="button-1"]').should('have.class', 'focus-indicator');

    // Verify focus indicators are removed when element loses focus
    cy.get('[data-testid="input-field"]').click();
    cy.get('[data-testid="input-field"]').should('not.have.class', 'focus-indicator');

    // Verify focus indicator is still visible on first element
    cy.get('[data-testid="button-1"]').should('have.class', 'focus-indicator');
  });
});
